1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	const displayTime = "2006-01-02 15:04:05 -07:00"
11	
12	func fmtTime(t time.Time) string { return t.Format(displayTime) }
13	
14	func fmtTimePtr(t *time.Time) string {
15		if t == nil {
16			return "-"
17		}
18		return fmtTime(*t)
19	}
20	
21	// FormatShift 格式化班次摘要。
22	func FormatShift(sh Shift) string {
23		state := "进行中"
24		if sh.Closed {
25			state = "已结束 " + fmtTimePtr(sh.ClosedAt)
26		}
27		return fmt.Sprintf("%s  岗位=%s  负责人=%s  %s ~ %s  [%s]",
28			sh.ID, sh.Position, sh.Owner, fmtTime(sh.Start), fmtTime(sh.End), state)
29	}
30	
31	// FormatItem 格式化事项及其关闭情况与历史。
32	func FormatItem(it Item) string {
33		var b strings.Builder
34		writeItemHeader(&b, it)
35		if len(it.Events) > 0 {
36			b.WriteString("  历史：\n")
37			for _, ev := range it.Events {
38				who := ""
39				if ev.Operator != "" {
40					who = " 操作人=" + ev.Operator
41				}
42				detail := ""
43				if ev.Detail != "" {
44					detail = " " + ev.Detail
45				}
46				fmt.Fprintf(&b, "    - %s %s%s%s\n", fmtTime(ev.At), ev.Kind, who, detail)
47			}
48		}
49		return b.String()
50	}
51	
52	// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
53	// 当前所在班次、关闭情况和流经班次。
54	func writeItemHeader(b *strings.Builder, it Item) {
55		state := "未关闭"
56		if it.Closed {
57			state = fmt.Sprintf("已关闭（%s 于 %s）", it.CloseOperator, fmtTimePtr(it.ClosedAt))
58		}
59		fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
60			it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
61		fmt.Fprintf(b, "  内容：%s\n", it.Content)
62		fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
63		fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
64		fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
65	}
66	
67	func dashIfEmpty(s string) string {
68		if s == "" {
69			return "-"
70		}
71		return s
72	}
73	
74	// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
75	func whoIfRecorded(s string) string {
76		if s == "" {
77			return "未记录"
78		}
79		return s
80	}
81	
82	// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
83	func fmtTimePtrIfRecorded(t *time.Time) string {
84		if t == nil {
85			return "未记录"
86		}
87		return fmtTimeIfRecorded(*t)
88	}
89	
90	// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
91	// 明确标为未记录，不显示公元元年日期。
92	func fmtTimeIfRecorded(t time.Time) string {
93		if t.IsZero() {
94			return "未记录"
95		}
96		return fmtTime(t)
97	}
98	
99	// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
100	// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
101	func fmtProcessedAtIfRecorded(t *time.Time) string {
102		if t == nil || t.IsZero() {
103			return "未记录"
104		}
105		return fmtTime(*t)
106	}
107	
108	// currentProcessing 返回交接单项当前处理结果的处理人与处理时间展示，是
109	// 交接清单（handover-show、shift-show 内嵌清单与末尾结果说明）和事项处理
110	// 经过查询（item-show）共用的同一条业务规则。
111	//
112	// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存无关：确认
113	// 接收、继续跟踪与退回都属于已经发生的处理，缺少处理时间不能使它们变成待
114	// 处理；真正待处理（含退回后已补充重新提交、等待接班人再次处理）的事项，
115	// 处理人与处理时间都显示尚未处理，即使旧记录残留姓名或时间也不显示成已处理。
116	//
117	// 已处理时处理人与处理时间各自独立展示：人名有值展示原姓名、缺失明确标为
118	// 未记录；时间有真实值沿用带时区格式、缺失或为旧数据零值
119	// （0001-01-01T00:00:00Z）同样标为未记录。缺少其中一个不能隐藏另一个，
120	// 也不以班次负责人、交接发起时间或退回历史中的信息代替。结果为空或无法
121	// 识别的记录同样按各自已保存的姓名与时间展示，不据以推测接收结果。
122	func currentProcessing(e HandoverEntry) (operator, processedAt string) {
123		if e.Status == EntryPending {
124			return "尚未处理", "尚未处理"
125		}
126		return whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt)
127	}
128	
129	// returnRoundView 是一轮退回历史在展示层的统一解读。交接查询
130	// （handover-show，及 shift-show 报告内嵌的交接清单）与班次报告末尾
131	// “各项交接当前结果”两处共用同一份判断，只保留各自的措辞、缩进与
132	// 字段次序——统一维护的是共同规则，不是把两处改成同一种文本。
133	type returnRoundView struct {
134		Seq            int
135		ReturnedAt     string // 退回时间：真实值用带时区格式；缺失或零值显示未记录
136		ReturnOperator string // 退回人：有值保留原姓名，缺失显示未记录
137		Reason         string // 该轮保存的退回原因，原样展示
138	
139		HasSupplement      bool   // 该轮是否保存了非空补充说明；没有就不产生补充段落
140		Supplement         string // 该轮保存的补充说明
141		SupplementOperator string // 补充人：缺失显示未记录
142		SupplementAt       string // 补充时间：缺失（nil）或零值显示未记录
143	
144		Resubmitted   bool   // 该轮是否保存了重新提交时间（旧数据零值也算已重新提交）
145		ResubmittedAt string // 重新提交时间：零值显示未记录；未保存时不展示该行
146	}
147	
148	// viewReturnRound 按共同规则解读一轮已保存的退回历史。它只做展示判断，
149	// 不补齐、不推测：
150	//   - 姓名有值保留原姓名、缺失显示未记录；时间缺失或为旧数据零值
151	//     （0001-01-01T00:00:00Z）显示未记录，真实时间沿用带时区格式，
152	//     姓名与时间各自独立判断，缺一个不隐藏另一个；
153	//   - 不用班次负责人、交接发起时间、当前处理人或其他轮次的资料补齐
154	//     本轮记录；
155	//   - 该轮没有非空补充说明时不产生补充段落；没有重新提交时间时不显示
156	//     已重新提交；保存了零值重新提交时间仍按已重新提交展示、时间显示
157	//     未记录，不悄悄改成尚未提交。
158	func viewReturnRound(r ReturnRound) returnRoundView {
159		v := returnRoundView{
160			Seq:            r.Seq,
161			ReturnedAt:     fmtTimeIfRecorded(r.ReturnedAt),
162			ReturnOperator: whoIfRecorded(r.ReturnOperator),
163			Reason:         r.Reason,
164			Resubmitted:    r.ResubmittedAt != nil,
165			ResubmittedAt:  fmtTimePtrIfRecorded(r.ResubmittedAt),
166		}
167		if r.Supplement != "" {
168			v.HasSupplement = true
169			v.Supplement = r.Supplement
170			v.SupplementOperator = whoIfRecorded(r.SupplementOperator)
171			v.SupplementAt = fmtTimePtrIfRecorded(r.SupplementAt)
172		}
173		return v
174	}
175	
176	// viewReturnRounds 按保存次序解读全部退回轮次，不增删、不重排、不补造：
177	// 连续发生多轮退回时每轮各用各的退回原因与补充说明，前一轮的原因和
178	// 补充不会被后一轮替换；没有退回轮次时返回空切片，调用方不补造轮次。
179	func viewReturnRounds(rounds []ReturnRound) []returnRoundView {
180		vs := make([]returnRoundView, len(rounds))
181		for i, r := range rounds {
182			vs[i] = viewReturnRound(r)
183		}
184		return vs
185	}
186	
187	// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
188	// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
189	// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
190	func entryCurrentResultLabel(s EntryStatus) string {
191		switch s {
192		case EntryPending:
193			return "待处理（接班人尚未处理）"
194		case EntryReturned:
195			return "退回（等待交班人补充）"
196		case EntryConfirmed:
197			return "确认接收"
198		case EntryTracking:
199			return "继续跟踪（已接收）"
200		case "":
201			return "处理结果未记录"
202		}
203		return "处理结果无法识别（原值：" + string(s) + "）"
204	}
205	
206	// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
207	// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
208	func FormatJourneyEvent(ev JourneyEvent) string {
209		when := "未记录"
210		if ev.TimeKnown {
211			when = fmtTime(ev.At)
212		}
213		who := whoIfRecorded(ev.Operator)
214		where := ""
215		if ev.HandoverID != "" {
216			where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
217		}
218		switch ev.Kind {
219		case "created":
220			return when + " 事项建立"
221		case "updated":
222			return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
223		case "closed":
224			return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
225		case "received":
226			return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
227		case "handover-init":
228			// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
229			return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
230		case "return":
231			return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
232				when, where, ev.RoundSeq, who, ev.Reason)
233		case "return-incomplete":
234			// 当前结果是退回却没有退回轮次记录：退回确实发生过，但轮次序号、
235			// 退回原因、补充与重新提交经过都没有可靠记录。处理人与时间各自使用
236			// 当前保存的信息（缺失分别标为未记录），并明确提示退回历史不完整、
237			// 原因未记录，不编造第几次退回，也不拿事项内容代替原因。
238			return fmt.Sprintf("%s %s退回 操作人=%s（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
239				when, where, who)
240		case "resubmit":
241			return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
242				when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
243				whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
244		case "confirm":
245			return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
246		case "track":
247			return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
248				when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
249		}
250		return when + " " + ev.Kind
251	}
252	
253	// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
254	// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
255	// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
256	func FormatItemJourney(j ItemJourney) string {
257		var b strings.Builder
258		writeItemHeader(&b, j.Item)
259	
260		b.WriteString("  处理经过：\n")
261		if len(j.Events) == 0 {
262			b.WriteString("    （暂无记录）\n")
263		}
264		for _, ev := range j.Events {
265			b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
266		}
267	
268		b.WriteString("  交接当前结果：\n")
269		if !j.HasHandovers {
270			b.WriteString("    暂无交接记录\n")
271		}
272		for _, r := range j.Results {
273			// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）。
274			operator, processedAt := currentProcessing(r.Entry)
275			fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
276				r.HandoverID, r.FromShift, r.ToShift,
277				entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
278		}
279		return b.String()
280	}
281	
282	// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
283	func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
284		var b strings.Builder
285		state := "结束时未关闭"
286		if snap.Closed {
287			state = fmt.Sprintf("结束时已关闭（%s 于 %s）", snap.CloseOperator, fmtTimePtr(snap.ClosedAt))
288		}
289		fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
290		fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
291		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
292		fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
293		if latest == nil {
294			b.WriteString("  最新状态：事项记录已不存在\n")
295			return b.String()
296		}
297		closeState := "未关闭"
298		if latest.Closed {
299			closeState = fmt.Sprintf("已关闭（%s 于 %s）", latest.CloseOperator, fmtTimePtr(latest.ClosedAt))
300		}
301		fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
302			latest.CurrentShiftID, latest.FollowOwner, closeState)
303		return b.String()
304	}
305	
306	// FormatOverlapNote 格式化重叠说明。
307	func FormatOverlapNote(n OverlapNote) string {
308		return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
309			n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
310	}
311	
312	// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
313	func FormatEntry(e HandoverEntry) string {
314		var b strings.Builder
315		fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
316			e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
317		fmt.Fprintf(&b, "  原文：%s\n", e.Content)
318		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
319		// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）；
320		// 待处理项在此额外说明等待接班人处理。
321		operator, processedAt := currentProcessing(e)
322		if e.Status == EntryPending {
323			fmt.Fprintf(&b, "  最后处理：尚未处理（等待接班人处理）；处理人=%s；处理时间=%s\n",
324				operator, processedAt)
325		} else {
326			fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n", operator, processedAt)
327		}
328		if e.Status == EntryTracking || e.TrackingNote != "" {
329			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
330			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
331		}
332		// 逐轮退回、补充与重新提交沿用共用的退回历史解读规则
333		// （见 viewReturnRound），保留本处原有措辞、缩进与字段次序。
334		for _, r := range viewReturnRounds(e.Rounds) {
335			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
336				r.Seq, r.ReturnedAt, r.ReturnOperator, r.Reason)
337			if r.HasSupplement {
338				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
339					r.Supplement, r.SupplementOperator, r.SupplementAt)
340			}
341			if r.Resubmitted {
342				fmt.Fprintf(&b, "    已重新提交：%s\n", r.ResubmittedAt)
343			}
344		}
345		return b.String()
346	}
347	
348	// FormatHandover 格式化完整交接记录。
349	func FormatHandover(h Handover) string {
350		var b strings.Builder
351		state := "未完成"
352		if h.Completed() {
353			state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
354		}
355		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
356			h.ID, h.Position, h.FromShiftID, h.ToShiftID,
357			fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
358		if len(h.Entries) == 0 {
359			b.WriteString("  （空清单，直接完成）\n")
360		}
361		for i := range h.Entries {
362			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
363		}
364		return b.String()
365	}
366	
367	func indentLines(s, prefix string) string {
368		return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
369	}
370	
371	// FormatReport 格式化按班次查询的完整报告。
372	func FormatReport(rep ShiftReport) string {
373		var b strings.Builder
374		b.WriteString("班次 " + FormatShift(rep.Shift) + "\n")
375	
376		b.WriteString("\n重叠说明：\n")
377		if len(rep.OverlapNotes) == 0 {
378			b.WriteString("  （无）\n")
379		}
380		for _, n := range rep.OverlapNotes {
381			b.WriteString(indentLines(FormatOverlapNote(n), "  "))
382		}
383	
384		if rep.ItemsAtClose {
385			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
386			if len(rep.CloseItems) == 0 {
387				b.WriteString("  （结束时没有事项）\n")
388			}
389			for _, s := range rep.CloseItems {
390				var latest *Item
391				if v, ok := rep.LatestItems[s.ItemID]; ok {
392					latest = &v
393				}
394				b.WriteString(indentLines(FormatCloseItem(s, latest), "  "))
395			}
396		} else {
397			if rep.HistoryIncomplete {
398				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
399			} else {
400				b.WriteString("\n事项：\n")
401			}
402			if len(rep.Items) == 0 {
403				b.WriteString("  （无）\n")
404			}
405			for _, it := range rep.Items {
406				b.WriteString(indentLines(FormatItem(it), "  "))
407			}
408		}
409	
410		b.WriteString("\n交班对象：\n")
411		if rep.Outgoing == nil {
412			b.WriteString("  （尚未发起交接）\n")
413		} else {
414			b.WriteString(indentLines(FormatHandover(*rep.Outgoing), "  "))
415		}
416	
417		b.WriteString("\n接班交接：\n")
418		if len(rep.Incoming) == 0 {
419			b.WriteString("  （无）\n")
420		}
421		for _, h := range rep.Incoming {
422			b.WriteString(indentLines(FormatHandover(h), "  "))
423		}
424	
425		b.WriteString("\n各项交接当前结果：\n")
426		if len(rep.Results) == 0 {
427			b.WriteString("  （无）\n")
428		}
429		ids := make([]string, 0, len(rep.Results))
430		for id := range rep.Results {
431			ids = append(ids, id)
432		}
433		sort.Strings(ids)
434		for _, id := range ids {
435			views := rep.Results[id]
436			for _, v := range views {
437				// 处理人与处理时间沿用共用的当前处理展示规则（见
438				// currentProcessing），与内嵌交接清单表达同一事实。
439				operator, processedAt := currentProcessing(v.Entry)
440				fmt.Fprintf(&b, "  事项 %s 交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
441					id, v.HandoverID, v.FromShift, v.ToShift,
442					v.Entry.Status.Label(), operator, processedAt)
443				// 退回历史与内嵌交接清单共用同一解读规则（见
444				// viewReturnRound），这里保留结果区原有的措辞、缩进与字段次序。
445				for _, r := range viewReturnRounds(v.Entry.Rounds) {
446					fmt.Fprintf(&b, "    第%d次退回：操作人=%s 时间=%s 原因=%s\n",
447						r.Seq, r.ReturnOperator, r.ReturnedAt, r.Reason)
448					if r.HasSupplement {
449						fmt.Fprintf(&b, "      补充：%s（补充人=%s，补充时间=%s）\n",
450							r.Supplement, r.SupplementOperator, r.SupplementAt)
451					}
452					if r.Resubmitted {
453						fmt.Fprintf(&b, "      已重新提交：%s\n", r.ResubmittedAt)
454					}
455				}
456			}
457		}
458		return b.String()
459	}
