// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
func fmtProcessedAtIfRecorded(t *time.Time) string {
	if t == nil || t.IsZero() {
		return "未记录"
	}
	return fmtTime(*t)
}

// closeInfoView 是一份关闭信息在展示层的统一解读。item-show 的事项最新状态
// 与 shift-show 的结束时记录、最新状态对照共用同一份判断，只保留各自的措辞
// 与前缀——统一维护的是共同规则，不是把各处改成同一种文本。
//
// 关闭与否只看已保存的关闭状态：状态为已关闭就按已关闭展示，关闭人或关闭
// 时间缺失不能使它变成未关闭；状态为未关闭时，即使旧数据残留关闭人或时间，
// 也不把它们当作一次有效关闭展示。
//
// 已关闭时关闭人与关闭时间各自独立判断：人名有值保留原姓名、未保存或为空
// 明确标为未记录；时间有真实值沿用带时区格式，未保存（nil）或为旧数据零值
// （0001-01-01T00:00:00Z）同样标为未记录。缺其中一个不隐藏另一个，也不
// 从事项最新值、班次负责人或处理经过补齐。
type closeInfoView struct {
	Closed         bool
	CloseOperator  string // 关闭人：有值保留原姓名，缺失显示未记录
	ClosedAt       string // 关闭时间：真实值用带时区格式；nil 或零值显示未记录
}

// viewCloseInfo 按共同规则解读已保存的关闭信息，只做展示判断，不补齐、
// 不推测。未关闭时不解读残留的关闭人或时间。
func viewCloseInfo(closed bool, operator string, at *time.Time) closeInfoView {
	v := closeInfoView{Closed: closed}
	if !closed {
		return v
	}
	v.CloseOperator = whoIfRecorded(operator)
	v.ClosedAt = fmtProcessedAtIfRecorded(at)
	return v
}

// closeDetail 输出关闭人与关闭时间的对照片段（“关闭人=…；关闭时间=…”），
// 供各处按自己的句式包裹。
func (v closeInfoView) detail() string {
	return fmt.Sprintf("关闭人=%s；关闭时间=%s", v.CloseOperator, v.ClosedAt)
}

